def find_lone_reading(readings):
    result = 0
    for i in range(32):
        count = 0
        for r in readings:
            count += (r >> i) & 1
        if count % 3:
            result |= 1 << i
    if result >= 1 << 31:
        result -= 1 << 32
    return result
